import pathlib,json,hashlib,re,sys
s=pathlib.Path(sys.argv[1]); results={}
for n in ['pack','monsters','items','roles']:
 a=(s/'before/schemas'/f'{n}.schema.json').read_bytes(); b=(s/'after/schemas'/f'{n}.schema.json').read_bytes()
 assert a==b, 'schema mismatch '+n
 results['schema/'+n]=hashlib.sha256(a).hexdigest()
for n in ['vanilla','hard-mode']:
 a=(s/'before'/f'{n}.nhpack').read_bytes(); b=(s/'after'/f'{n}.nhpack').read_bytes()
 assert a==b, 'pack bytes mismatch '+n
 p=json.loads(a); h=p['hash']; assert re.fullmatch(r'sha256:[0-9a-f]{64}',h)
 for phase in ['before','after']:
  assert (s/phase/f'{n}-build.stdout').read_text().strip()==h, 'build hash mismatch'
 results[n]={'canonical_hash':h,'bytes_sha256':hashlib.sha256(a).hexdigest()}
p=json.loads((s/'inputs/old-item-profiles.nhpack').read_bytes()); h=p['hash']
for phase in ['before','after']:
 for n in ['vanilla','hard-mode','old-item-profiles']:
  expected=h if n=='old-item-profiles' else results[n]['canonical_hash']
  text=(s/phase/f'{n}-validate.stdout').read_text()
  assert '(hash: '+expected+')' in text, 'native verified hash mismatch '+phase+'/'+n
results['old-item-profiles']={'canonical_hash':h,'bytes_sha256':hashlib.sha256((s/'inputs/old-item-profiles.nhpack').read_bytes()).hexdigest()}
# Compare frozen production inputs and every preexisting integration test/setup to pinned baseline.
r=pathlib.Path(sys.argv[2]); baseline=s/'baseline-src'; frozen=[]
for p in sorted(baseline.rglob('*')):
 if not p.is_file(): continue
 rel=p.relative_to(baseline); name=rel.as_posix()
 if name.startswith(('crates/nethacked-pack/','crates/nethacked-data/','crates/nethacked-types/','data/','packs/','scripts/extract/')) or '/tests/' in name or '.schema.' in name or name in ['Cargo.toml','Cargo.lock']:
  assert (r/rel).is_file() and (r/rel).read_bytes()==p.read_bytes(), 'frozen source/setup changed '+name
  frozen.append(name)
results['frozen_production_and_existing_tests']={'count':len(frozen),'result':'byte-identical'}
(s/'comparison.json').write_text(json.dumps(results,indent=2))
json.loads((s/'comparison.json').read_text())
